<?php require_once __DIR__.'/includes/config.php';require_login();require_permission('customers');$uid=(int)$_SESSION['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'add';if($action==='add'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'')?:null;if($name===''||mb_strlen($name)>140)$errors[]='Enter the customer name.';if($phone!==null&&mb_strlen($phone)>40)$errors[]='Phone number is too long.';if(!$errors){$q=$pdo->prepare('INSERT INTO customers(user_id,name,phone) VALUES(?,?,?)');$q->execute([$uid,$name,$phone]);flash('Customer added.');redirect('customers.php');}}elseif($action==='payment'){$saleId=filter_var($_POST['sale_id']??null,FILTER_VALIDATE_INT);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$note=trim($_POST['note']??'');$q=$pdo->prepare('SELECT s.id,s.total,s.amount_paid FROM sales s WHERE s.id=? AND s.user_id=? FOR UPDATE');$pdo->beginTransaction();$q->execute([$saleId,$uid]);$sale=$q->fetch();if(!$sale||$amount===false||$amount<=0||$amount>(float)$sale['total']-(float)$sale['amount_paid']+0.001){$pdo->rollBack();$errors[]='Enter a valid payment no greater than the outstanding balance.';}else{$q=$pdo->prepare('INSERT INTO debt_payments(user_id,sale_id,amount,note) VALUES(?,?,?,?)');$q->execute([$uid,$saleId,$amount,$note?:null]);$q=$pdo->prepare('UPDATE sales SET amount_paid=amount_paid+? WHERE id=? AND user_id=?');$q->execute([$amount,$saleId,$uid]);$pdo->commit();flash('Debt payment recorded.');redirect('customers.php');}}}
$q=$pdo->prepare('SELECT c.*,COALESCE(SUM(s.total-s.amount_paid),0) balance FROM customers c LEFT JOIN sales s ON s.customer_id=c.id AND s.user_id=c.user_id GROUP BY c.id ORDER BY c.name');$q->execute();$customers=$q->fetchAll();$q=$pdo->prepare('SELECT s.id,s.total,s.amount_paid,c.name FROM sales s JOIN customers c ON c.id=s.customer_id WHERE s.user_id=? AND s.total>s.amount_paid ORDER BY s.created_at');$q->execute([$uid]);$debts=$q->fetchAll();$pageTitle='Customers';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Customers & debts</h1><p class="muted mb-0">Keep customer contact details and track credit repayments.</p></div></div><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?>
<div class="row g-4"><div class="col-lg-4"><div class="card"><div class="card-body p-4"><h2 class="h5 fw-bold mb-3">Add customer</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="mb-3"><label class="form-label">Customer name</label><input class="form-control" name="name" maxlength="140" required></div><div class="mb-3"><label class="form-label">Phone (optional)</label><input class="form-control" name="phone" maxlength="40"></div><button class="btn btn-primary">Save customer</button></form></div></div><div class="card mt-3"><div class="card-body p-4"><h2 class="h5 fw-bold mb-3">Record debt payment</h2><?php if(!$debts):?><p class="muted mb-0">No outstanding customer debts yet.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="payment"><div class="mb-3"><label class="form-label">Outstanding sale</label><select class="form-select" name="sale_id" required><?php foreach($debts as $d):?><option value="<?=(int)$d['id']?>">#<?=(int)$d['id']?> · <?=e($d['name'])?> · <?=money((float)$d['total']-(float)$d['amount_paid'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Amount received (₦)</label><input class="form-control" type="number" min="0.01" step="0.01" name="amount" required></div><div class="mb-3"><label class="form-label">Note (optional)</label><input class="form-control" name="note" maxlength="255"></div><button class="btn btn-primary">Record payment</button></form><?php endif;?></div></div></div><div class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Customer list</h2><div class="table-responsive"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Outstanding</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td class="fw-semibold"><?=e($c['name'])?></td><td><?=e($c['phone']??'—')?></td><td class="<?=((float)$c['balance']>0?'text-danger':'text-success')?> fw-semibold"><?=money($c['balance'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$customers):?><div class="empty-state">Add a customer to get started.</div><?php endif;?></div></div></div></div></div><?php require __DIR__.'/includes/footer.php';?>
